arguments.command:
cd /work && python3 -c "
import re,csv
rows=list(csv.DictReader(open('b3_supercon_data.csv')))
def parse(s):
    d={}
    for el,n in re.findall(r'([A-Z][a-z]?)([0-9.]*)',s):
        if el: d[el]=d.get(el,0)+(float(n) if n else 1.0)
    return d
data=[(parse(r['composition']),float(r['target']),r['composition']) for r in rows]
data.sort(key=lambda x:-x[1])
for d,t,c in data[:25]:
    tot=sum(d.values())
    print(round(t,1),c,{k:round(v/tot,4) for k,v in d.items()})
"

